  q: "経理部長は予算とリソース配置の決定権を持つが、テストの日々の進捗にはあまり関心がない。コールセンターのリーダーは影響力は小さいが、新機能の品質に強い関心を持っている。ステークホルダーマトリクスに基づく分類と対応の組み合わせとして正しいものはどれか。",
