    "経理部長＝推進者：テスト戦略の形成に日常的に参加させる／リーダー＝無関心者：重要なマイルストーンでのみ報告して関心の低下を防ぐ",
    "経理部長＝無関心者：重要なマイルストーンでのみ報告する／リーダー＝推進者：テスト計画の形成に主要協力者として日常的に参加させる",
