  q: "次のテスト目的が示された。「今年度末までに、リグレッションテストの自動化率を現状の20%から95%に向上させる。」ただし、自動化ツールの予算も、自動化を担当する要員も確保されておらず、今年度の残りは3か月である。SMARTの法則の観点で、最も問題がある要素はどれか。",
