  answer: 33000, unit: "ドル",
  expl: "欠陥1件あたりの平均節約額 ＝ 4,000 −（500 ＋ 200）＝ 3,300ドル（シラバスの計算例と同じ）。10件なので 3,300 × 10 ＝ 33,000ドル。"
