/*
 * 用語集データ（当サイト独自の説明。ISTQB/JSTQB の公式用語集の転載ではない）
 *   term : 用語（JSTQB シラバス日本語版の表記）
 *   yomi : 読み（並べ替え・検索用、ひらがな）
 *   en   : 英語表記
 *   cat  : 分類
 *   def  : 説明
 *   note : 現場でよくある呼び方・混同しやすい点（任意）
 *   see  : 関連する用語（任意）
 *   sec  : 根拠となるシラバスの節（FL / TM）
 */
window.GLOSSARY = [
/* ---------- 基本 ---------- */
{ term: "テスト", yomi: "てすと", en: "testing", cat: "基本",
  def: "欠陥を見つけ、ソフトウェアやその作業成果物の品質を評価するための一連の活動。テストの実行だけでなく、計画・分析・設計・実装・完了なども含む。要件どおりかの「検証」と、ニーズを満たすかの「妥当性確認」の両方を行う。",
  note: "「テスト＝テストを実行すること」と狭く捉えられがちだが、シラバスでは計画からレポートまでを含む一連の活動を指す。",
  see: ["デバッグ", "検証", "妥当性確認"], sec: "FL 1.1" },
{ term: "デバッグ", yomi: "でばっぐ", en: "debugging", cat: "基本",
  def: "故障の原因（欠陥）を見つけ、解析し、取り除く活動。典型的には「故障の再現 → 診断 → 修正」の流れで行う。テストとは別の活動である。",
  note: "「バグ取り」全般をテストと呼ぶこともあるが、欠陥を取り除くのはデバッグであってテストではない。修正後に行うのは確認テスト。",
  see: ["テスト", "確認テスト"], sec: "FL 1.1.2" },
{ term: "エラー（誤り）", yomi: "えらー", en: "error / mistake", cat: "基本",
  def: "人間が犯す誤り。仕様の読み違えや思い込みなど。エラーが欠陥を生み出す。",
  note: "画面に出る「エラーメッセージ」や故障そのものを「エラー」と呼ぶことが多いが、シラバスでは「人の誤り」を指す。",
  see: ["欠陥", "故障", "根本原因"], sec: "FL 1.2.3" },
{ term: "欠陥", yomi: "けっかん", en: "defect / fault / bug", cat: "基本",
  def: "作業成果物（コード、要件仕様書、テストスクリプトなど）の中にある不備。フォールトやバグとも呼ばれる。実行されると故障につながることがある。",
  note: "「バグ」と同じ意味で使ってよい。ドキュメントの中の不備も欠陥に含まれる点に注意。",
  see: ["エラー（誤り）", "故障"], sec: "FL 1.2.3" },
{ term: "故障", yomi: "こしょう", en: "failure", cat: "基本",
  def: "欠陥が実行された結果、システムがすべきことをしない、またはすべきでないことをしてしまうこと。環境条件（放射線や電磁波など）が原因で起こることもある。",
  note: "「障害」と呼ばれることが多い（「不具合」は欠陥と故障のどちらの意味でも使われるので注意）。典型的には「エラー → 欠陥 → 故障」の順に因果関係があるが、環境条件のように欠陥によらない故障もある。",
  see: ["エラー（誤り）", "欠陥"], sec: "FL 1.2.3" },
{ term: "根本原因", yomi: "こんぽんげんいん", en: "root cause", cat: "基本",
  def: "問題が起きる根底の理由。根本原因分析で特定し、対処することで同様の故障や欠陥の防止や頻度の低減が期待できる。",
  see: ["エラー（誤り）"], sec: "FL 1.2.3" },
{ term: "不正", yomi: "ふせい", en: "anomaly", cat: "基本",
  def: "期待と異なる事象。報告された不正は、調べると本当の欠陥のこともあれば、偽陽性や変更要求などのこともある。",
  note: "「不正アクセス」の不正ではない。英語の anomaly（異常・食い違い）の訳語。",
  see: ["欠陥レポート"], sec: "FL 5.5" },
{ term: "検証", yomi: "けんしょう", en: "verification", cat: "基本",
  def: "指定された要件をシステムが満たしているかを確認すること。「仕様どおりに作られているか」を見る。",
  note: "「検証＝テスト全般」の意味で使われがちだが、シラバスでは妥当性確認と区別する。",
  see: ["妥当性確認"], sec: "FL 1.1" },
{ term: "妥当性確認", yomi: "だとうせいかくにん", en: "validation", cat: "基本",
  def: "ユーザーやステークホルダーのニーズを、運用環境でシステムが満たしているかを確認すること。「正しいものを作ったか」を見る。",
  note: "仕様どおりでも使われないシステムになりうる（「欠陥ゼロ」の落とし穴）ため、検証と妥当性確認の両方が必要。",
  see: ["検証"], sec: "FL 1.1, 1.3" },
{ term: "品質保証（QA）", yomi: "ひんしつほしょう", en: "quality assurance", cat: "基本",
  def: "プロセスの実装と改善に焦点を当てた、プロセス指向の予防的アプローチ。プロジェクトに参加するすべての人が責任を持つ。",
  note: "日本の現場では「QA＝テストをする人・部署」の意味で使われることが多いが、シラバスではテストはQAではなく品質コントロール（QC）の一形式とされる。",
  see: ["品質コントロール（QC）"], sec: "FL 1.2.2" },
{ term: "品質コントロール（QC）", yomi: "ひんしつこんとろーる", en: "quality control", cat: "基本",
  def: "適切な品質の達成を支援する活動に焦点を当てた、プロダクト指向の是正アプローチ。テストはその主要な形式である。",
  see: ["品質保証（QA）"], sec: "FL 1.2.2" },
{ term: "テストベース", yomi: "てすとべーす", en: "test basis", cat: "基本",
  def: "テスト分析やテスト設計のよりどころになる情報。要件仕様書、ユーザーストーリー、設計書、コードなど。",
  note: "「テストの元ネタ」「インプット資料」と呼ばれるもの。",
  see: ["テスト条件"], sec: "FL 1.4.1" },
{ term: "テスト対象", yomi: "てすとたいしょう", en: "test object", cat: "基本",
  def: "テストされる作業成果物（コンポーネントやシステムなど）。",
  see: ["テストベース"], sec: "FL 1.1" },
{ term: "テスト条件", yomi: "てすとじょうけん", en: "test condition", cat: "基本",
  def: "テスト分析で識別する「何をテストするか」。テスト可能な機能や特性など。受け入れ基準もテスト条件とみなせる。",
  note: "現場の「テスト観点」「確認項目」に近い。テストケースより抽象度が高い。",
  see: ["テストケース", "テストベース"], sec: "FL 1.4.1, 1.4.3" },
{ term: "テストケース", yomi: "てすとけーす", en: "test case", cat: "基本",
  def: "テスト設計で、テスト条件を具体化したもの。事前条件・入力・期待結果などを含む。",
  note: "「テスト項目」と呼ぶ現場も多い。複数のテストケースを実行順にまとめたものがテストプロシジャー。",
  see: ["テスト条件", "テストプロシジャー", "テストスイート"], sec: "FL 1.4.1" },
{ term: "テストプロシジャー", yomi: "てすとぷろしじゃー", en: "test procedure", cat: "基本",
  def: "テストケースを実行する手順をまとめたもの。テスト実装で作成する。",
  note: "現場の「テスト手順書」に当たる。",
  see: ["テストケース", "テストスイート"], sec: "FL 1.4.1" },
{ term: "テストスイート", yomi: "てすとすいーと", en: "test suite", cat: "基本",
  def: "テストケースやテストプロシジャーを、まとめて実行するためにグループにしたもの。",
  see: ["テストプロシジャー"], sec: "FL 1.4.1" },
{ term: "テストウェア", yomi: "てすとうぇあ", en: "testware", cat: "基本",
  def: "テスト活動で作られる作業成果物の総称。テスト計画書、テスト条件、テストケース、テストデータ、テスト環境、レポートなど。",
  see: ["テストケース"], sec: "FL 1.4.3" },
{ term: "テストチャーター", yomi: "てすとちゃーたー", en: "test charter", cat: "基本",
  def: "探索的テストで、テストセッションの目的や重点を示したもの。テスト設計の作業成果物。",
  see: ["探索的テスト"], sec: "FL 1.4.3, 4.4.2" },
{ term: "カバレッジ", yomi: "かばれっじ", en: "coverage", cat: "基本",
  def: "カバレッジアイテムのうち、テストで通過した（確認した）ものの割合。パーセンテージで表す。",
  note: "コードの網羅率だけを指すことが多いが、要件カバレッジやリスクカバレッジなど、何を分母にするかで種類がある。",
  see: ["カバレッジアイテム", "ステートメントカバレッジ", "ブランチカバレッジ"], sec: "FL 4" },
{ term: "カバレッジアイテム", yomi: "かばれっじあいてむ", en: "coverage item", cat: "基本",
  def: "カバレッジを測るときに数える単位。同値分割法ではパーティション、デシジョンテーブルテストでは実行可能な列、状態遷移テストでは状態や遷移など、技法ごとに異なる。",
  see: ["カバレッジ"], sec: "FL 4.2" },
{ term: "トレーサビリティ", yomi: "とれーさびりてぃ", en: "traceability", cat: "基本",
  def: "テストベースの各要素と、テスト条件・テストケース・テスト結果・欠陥などとの対応関係を追えるようにしておくこと。カバレッジの評価や変更の影響の判断に役立つ。",
  note: "現場の「トレーサビリティマトリクス」「要件とテストの対応表」。",
  sec: "FL 1.4.4" },

/* ---------- テストレベル・テストタイプ ---------- */
{ term: "テストレベル", yomi: "てすとれべる", en: "test level", cat: "テストレベル・テストタイプ",
  def: "系統的にまとめてマネジメントするテスト活動のグループ。FLシラバスでは、コンポーネントテスト、コンポーネント統合テスト、システムテスト、システム統合テスト、受け入れテストの5つを扱う。",
  note: "「テスト工程」「テストフェーズ」と呼ばれることが多い。テストタイプとの違いに注意。",
  see: ["テストタイプ"], sec: "FL 2.2.1" },
{ term: "コンポーネントテスト", yomi: "こんぽーねんとてすと", en: "component testing", cat: "テストレベル・テストタイプ",
  def: "コンポーネントを単独でテストするテストレベル。ユニットテストとも呼ばれ、通常は開発担当者が開発環境で行う。",
  note: "現場の「単体テスト（UT）」に当たる。",
  see: ["コンポーネント統合テスト"], sec: "FL 2.2.1" },
{ term: "コンポーネント統合テスト", yomi: "こんぽーねんととうごうてすと", en: "component integration testing", cat: "テストレベル・テストタイプ",
  def: "コンポーネント間のインターフェースと相互処理に焦点を当てるテストレベル。ボトムアップ、トップダウン、ビッグバンなどの統合戦略に大きく依存する。",
  note: "現場の「結合テスト（IT）」のうち、同じシステム内の部品同士をつなぐもの。外部システムとの結合はシステム統合テスト。",
  see: ["システム統合テスト"], sec: "FL 2.2.1" },
{ term: "システムテスト", yomi: "しすてむてすと", en: "system testing", cat: "テストレベル・テストタイプ",
  def: "システム全体の振る舞いや能力に焦点を当てるテストレベル。エンドツーエンドの機能テストや、品質特性に対する非機能テストを行う。",
  note: "現場の「総合テスト（ST）」に当たることが多い。",
  sec: "FL 2.2.1" },
{ term: "システム統合テスト", yomi: "しすてむとうごうてすと", en: "system integration testing", cat: "テストレベル・テストタイプ",
  def: "テスト対象システムと、他のシステムや外部サービスとのインターフェースに焦点を当てるテストレベル。",
  note: "「外部結合テスト」「連携テスト」と呼ばれることがある。",
  see: ["コンポーネント統合テスト"], sec: "FL 2.2.1" },
{ term: "受け入れテスト", yomi: "うけいれてすと", en: "acceptance testing", cat: "テストレベル・テストタイプ",
  def: "妥当性確認と、デプロイの準備ができていることの実証に焦点を当てるテストレベル。想定ユーザーが行うのが理想。ユーザー受け入れテスト（UAT）、運用受け入れテスト、契約・規制による受け入れテスト、アルファテスト・ベータテストなどの形式がある。",
  note: "現場の「UAT」「受入試験」。",
  sec: "FL 2.2.1" },
{ term: "テストタイプ", yomi: "てすとたいぷ", en: "test type", cat: "テストレベル・テストタイプ",
  def: "特定の品質特性に関連するテスト活動のグループ。FLシラバスでは、機能テスト、非機能テスト、ブラックボックステスト、ホワイトボックステストの4つを扱う。ほとんどはすべてのテストレベルで実行できる。",
  note: "「どの段階でやるか」がテストレベル、「何の特性を見るか」がテストタイプ。",
  see: ["テストレベル"], sec: "FL 2.2.2" },
{ term: "機能テスト", yomi: "きのうてすと", en: "functional testing", cat: "テストレベル・テストタイプ",
  def: "テスト対象が「何」をすべきかを評価するテスト。機能完全性、機能正確性、機能適切性をチェックする。",
  see: ["非機能テスト"], sec: "FL 2.2.2" },
{ term: "非機能テスト", yomi: "ひきのうてすと", en: "non-functional testing", cat: "テストレベル・テストタイプ",
  def: "システムが「どのようにうまく振る舞うか」を評価するテスト。性能効率性、互換性、使用性、信頼性、セキュリティ、保守性、移植性などの品質特性を対象とする。",
  note: "「性能テスト＝非機能テスト」と狭く捉えがちだが、使用性やセキュリティなども含む。",
  see: ["機能テスト"], sec: "FL 2.2.2" },
{ term: "確認テスト", yomi: "かくにんてすと", en: "confirmation testing", cat: "テストレベル・テストタイプ",
  def: "元の欠陥が正しく修正されたことを確認するテスト。",
  note: "現場の「再テスト」「修正確認」に当たる。リグレッションテストとは目的が違う。",
  see: ["リグレッションテスト", "デバッグ"], sec: "FL 2.2.3" },
{ term: "リグレッションテスト", yomi: "りぐれっしょんてすと", en: "regression testing", cat: "テストレベル・テストタイプ",
  def: "変更（欠陥の修正を含む）によって、変更していない部分や接続する他システムなどに悪影響が出ていないことを確認するテスト。繰り返し実行するため、自動化の有力な候補になる。",
  note: "現場の「回帰テスト」「デグレ確認」に当たる。「デグレ（デグレード）」は和製の言い方で、リグレッション（退行）が本来の表現。",
  see: ["確認テスト"], sec: "FL 2.2.3" },
{ term: "メンテナンステスト", yomi: "めんてなんすてすと", en: "maintenance testing", cat: "テストレベル・テストタイプ",
  def: "稼働中のシステムへの変更に対して行うテスト。きっかけには、変更（計画された機能拡張、是正のための変更、ホットフィックスなど）、運用環境の更新・移行、廃棄がある。",
  note: "現場の「保守テスト」「改修時のテスト」。",
  sec: "FL 2.3" },
{ term: "シフトレフト", yomi: "しふとれふと", en: "shift left", cat: "テストレベル・テストタイプ",
  def: "テストをSDLCのより早い段階で行うアプローチ。仕様書のレビュー、コードを書く前のテストケース作成、CIでの自動テスト、早期の静的解析などが例。後半のテストを軽視するという意味ではない。",
  sec: "FL 2.1.5" },

/* ---------- 静的テスト ---------- */
{ term: "静的テスト", yomi: "せいてきてすと", en: "static testing", cat: "静的テスト",
  def: "ソフトウェアを実行せずに行うテスト。レビューと静的解析が含まれる。欠陥を直接見つけられる。",
  note: "「テスト＝動かして確認」と考えられがちだが、レビューもテストの一種と位置づけられている。",
  see: ["動的テスト", "レビュー", "静的解析"], sec: "FL 3.1" },
{ term: "動的テスト", yomi: "どうてきてすと", en: "dynamic testing", cat: "静的テスト",
  def: "ソフトウェアを実行して行うテスト。故障を引き起こし、その分析によって欠陥を特定する。",
  see: ["静的テスト"], sec: "FL 3.1.3" },
{ term: "レビュー", yomi: "れびゅー", en: "review", cat: "静的テスト",
  def: "人が作業成果物を読んで評価する静的テスト。形式の度合いにより、非形式的レビュー、ウォークスルー、テクニカルレビュー、インスペクションなどの種別がある。",
  see: ["インスペクション", "ウォークスルー"], sec: "FL 3.2" },
{ term: "ウォークスルー", yomi: "うぉーくするー", en: "walkthrough", cat: "静的テスト",
  def: "作成者が主導するレビュー。品質評価、レビューアの教育、合意形成、アイデアの創出、不正の検出など多くの目的を持つ。事前の個人レビューは必須ではない。",
  see: ["レビュー", "インスペクション"], sec: "FL 3.2.4" },
{ term: "インスペクション", yomi: "いんすぺくしょん", en: "inspection", cat: "静的テスト",
  def: "最も形式的なレビュー。汎用レビュープロセスに完全に従い、不正を最大数発見することが主な目的。作成者はレビューリーダーや書記になれない。",
  see: ["レビュー", "ウォークスルー"], sec: "FL 3.2.4" },
{ term: "静的解析", yomi: "せいてきかいせき", en: "static analysis", cat: "静的テスト",
  def: "ツールを使って、コードなどの作業成果物を実行せずに評価すること。未定義の変数や到達不能コード、コーディング標準からの逸脱などを見つけられる。CIに組み込まれることが多い。",
  see: ["静的テスト"], sec: "FL 3.1" },

/* ---------- テスト技法 ---------- */
{ term: "ブラックボックステスト技法", yomi: "ぶらっくぼっくすてすとぎほう", en: "black-box test technique", cat: "テスト技法",
  def: "テスト対象の内部構造を参照せず、仕様上の振る舞いの分析に基づいてテストを導出する技法。仕様ベース技法とも呼ばれる。",
  see: ["ホワイトボックステスト技法", "同値分割法", "境界値分析"], sec: "FL 4.1, 4.2" },
{ term: "同値分割法", yomi: "どうちぶんかつほう", en: "equivalence partitioning", cat: "テスト技法",
  def: "同じように処理されると想定される値の集まり（同値パーティション）に分け、各パーティションから代表値を選んでテストする技法。無効パーティションもカバレッジに含める。",
  note: "現場の「同値クラス」「同値分析」。",
  see: ["境界値分析"], sec: "FL 4.2.1" },
{ term: "境界値分析", yomi: "きょうかいちぶんせき", en: "boundary value analysis", cat: "テスト技法",
  def: "順序性のあるパーティションの境界（最小値・最大値）に着目してテストする技法。境界値とその隣を確認する2値BVAと、境界値と両隣を確認する3値BVAがある。",
  note: "「境界値テスト」とも。どの値を境界値として数えるかは、2値か3値かで異なる。",
  see: ["同値分割法"], sec: "FL 4.2.2" },
{ term: "デシジョンテーブルテスト", yomi: "でしじょんてーぶるてすと", en: "decision table testing", cat: "テスト技法",
  def: "条件の組み合わせと、それに対応する結果（アクション）を表にまとめ、実行可能な組み合わせ（列）ごとにテストする技法。",
  note: "現場の「決定表」「条件の組み合わせ表」。",
  sec: "FL 4.2.3" },
{ term: "状態遷移テスト", yomi: "じょうたいせんいてすと", en: "state transition testing", cat: "テスト技法",
  def: "システムの状態と、イベントによる状態間の遷移をモデル（状態遷移図・状態表）にして、状態や遷移をカバーするテストを導出する技法。全状態カバレッジ、有効遷移カバレッジ、全遷移カバレッジなどの基準がある。",
  sec: "FL 4.2.4" },
{ term: "ホワイトボックステスト技法", yomi: "ほわいとぼっくすてすとぎほう", en: "white-box test technique", cat: "テスト技法",
  def: "テスト対象の内部構造や処理の分析に基づいてテストを導出する技法。構造ベース技法とも呼ばれる。",
  see: ["ステートメントカバレッジ", "ブランチカバレッジ"], sec: "FL 4.3" },
{ term: "ステートメントカバレッジ", yomi: "すてーとめんとかばれっじ", en: "statement coverage", cat: "テスト技法",
  def: "実行可能なステートメントのうち、テストで通過したものの割合。",
  note: "現場の「命令網羅」「C0（シーゼロ）カバレッジ」。C0・C1という呼び方はシラバスには出てこない現場の通称。",
  see: ["ブランチカバレッジ"], sec: "FL 4.3.1" },
{ term: "ブランチカバレッジ", yomi: "ぶらんちかばれっじ", en: "branch coverage", cat: "テスト技法",
  def: "制御フローのブランチ（無条件・条件付きの制御の遷移）のうち、テストで通過したものの割合。ブランチカバレッジ100%はステートメントカバレッジ100%を包含する。",
  note: "現場の「分岐網羅」「C1カバレッジ」。",
  see: ["ステートメントカバレッジ"], sec: "FL 4.3.2" },
{ term: "エラー推測", yomi: "えらーすいそく", en: "error guessing", cat: "テスト技法",
  def: "過去の故障や、開発担当者が起こしやすいエラーなど、テスト担当者の知識に基づいて欠陥を予測してテストする経験ベースの技法。系統的なやり方としてフォールト攻撃がある。",
  sec: "FL 4.4.1" },
{ term: "探索的テスト", yomi: "たんさくてきてすと", en: "exploratory testing", cat: "テスト技法",
  def: "テスト対象について学びながら、テストの設計・実行・評価を同時に行う経験ベースの技法。セッションベースドテストで体系的に行うことがある。",
  note: "「アドホックテスト（思いつきで触る）」と混同されがちだが、テストチャーターと時間枠を決めて行う体系的なやり方がある。",
  see: ["テストチャーター"], sec: "FL 4.4.2" },
{ term: "チェックリストベースドテスト", yomi: "ちぇっくりすとべーすどてすと", en: "checklist-based testing", cat: "テスト技法",
  def: "チェックリストのテスト条件をカバーするようにテストを行う経験ベースの技法。チェックリストは欠陥分析に基づいて定期的に更新する。",
  sec: "FL 4.4.3" },
{ term: "受け入れテスト駆動開発（ATDD）", yomi: "うけいれてすとくどうかいはつ", en: "acceptance test-driven development", cat: "テスト技法",
  def: "ユーザーストーリーの実装前に、顧客・開発担当者・テスト担当者などが受け入れ基準からテストケースを作るテストファーストのアプローチ。",
  see: ["テスト駆動開発（TDD）", "振る舞い駆動開発（BDD）"], sec: "FL 2.1.3, 4.5.3" },
{ term: "テスト駆動開発（TDD）", yomi: "てすとくどうかいはつ", en: "test-driven development", cat: "テスト技法",
  def: "テストを先に書き、テストを満たすコードを書き、テストとコードをリファクタリングする、という流れでコーディングを導く開発手法。",
  see: ["受け入れテスト駆動開発（ATDD）"], sec: "FL 2.1.3" },
{ term: "振る舞い駆動開発（BDD）", yomi: "ふるまいくどうかいはつ", en: "behavior-driven development", cat: "テスト技法",
  def: "望ましい振る舞いを、ステークホルダーが理解しやすい自然言語（通常 Given/When/Then 形式）で表したテストケースで開発を導く手法。テストケースは実行可能なテストへ自動的に変換する。",
  see: ["受け入れテスト駆動開発（ATDD）"], sec: "FL 2.1.3" },

/* ---------- マネジメント ---------- */
{ term: "テスト計画書", yomi: "てすとけいかくしょ", en: "test plan", cat: "マネジメント",
  def: "テストの目的、リソース、プロセスを記述した文書。スコープ、前提と制約、ステークホルダー、リスクレジスター、テストアプローチ、予算とスケジュールなどを含む。",
  sec: "FL 5.1.1" },
{ term: "開始基準", yomi: "かいしきじゅん", en: "entry criteria", cat: "マネジメント",
  def: "ある活動を始めるための事前条件。リソースやテストウェアの可用性、テスト対象の初期品質レベル（スモークテストの合格など）がある。アジャイルでは準備完了（Ready）の定義と呼ばれることが多い。",
  see: ["終了基準"], sec: "FL 5.1.3" },
{ term: "終了基準", yomi: "しゅうりょうきじゅん", en: "exit criteria", cat: "マネジメント",
  def: "活動の完了を宣言するために達成すべきこと。カバレッジや未解決欠陥の数などの徹底度の測定と、計画したテストの実行などの完了基準がある。アジャイルでは完了（Done）の定義と呼ばれることが多い。",
  see: ["開始基準"], sec: "FL 5.1.3" },
{ term: "リスク", yomi: "りすく", en: "risk", cat: "マネジメント",
  def: "顕在化すると悪影響が生じる、潜在的な事象・ハザード・脅威・状況。リスクの可能性とリスクの影響の2つで特徴づけられる。",
  see: ["リスクレベル", "プロダクトリスク", "プロジェクトリスク"], sec: "FL 5.2.1" },
{ term: "リスクレベル", yomi: "りすくれべる", en: "risk level", cat: "マネジメント",
  def: "リスクの可能性とリスクの影響から決まるリスクの大きさ。定量的には両者の積で、定性的にはリスクマトリクスで決める。",
  see: ["リスク"], sec: "FL 5.2.1, 5.2.3 / TM 1.3.3" },
{ term: "プロダクトリスク", yomi: "ぷろだくとりすく", en: "product risk", cat: "マネジメント",
  def: "プロダクトの品質特性に関するリスク。機能の不足や誤り、応答時間の不足、セキュリティの脆弱性など。品質リスクとも呼ばれる。",
  see: ["プロジェクトリスク"], sec: "FL 5.2.2 / TM 1.3" },
{ term: "プロジェクトリスク", yomi: "ぷろじぇくとりすく", en: "project risk", cat: "マネジメント",
  def: "プロジェクトのマネジメントや統制に関するリスク。組織・人・技術・サプライヤーの問題などで、スケジュールや予算、スコープに影響する。",
  see: ["プロダクトリスク"], sec: "FL 5.2.2" },
{ term: "リスクベースドテスト", yomi: "りすくべーすどてすと", en: "risk-based testing", cat: "マネジメント",
  def: "リスク分析とリスクコントロールに基づいて、テスト活動を選択し、優先順位を付け、マネジメントするテストアプローチ。リスクレベルが高いほど早く、厳密に、多くの労力でテストする。",
  see: ["リスクレベル"], sec: "FL 5.2 / TM 1.3" },
{ term: "テスト戦略", yomi: "てすとせんりゃく", en: "test strategy", cat: "マネジメント",
  def: "特定のコンテキストでのテストへのアプローチを記述したもの。組織全体の組織的テスト戦略と、それに沿ったプロジェクトテスト戦略がある。",
  sec: "TM 1.4" },
{ term: "重要度", yomi: "じゅうようど", en: "severity", cat: "マネジメント",
  def: "欠陥がステークホルダーの利益や要件に与える影響の度合い。",
  note: "優先度（どれから直すか）と混同されやすい。影響は小さいが目立つ誤字のように「重要度は低いが優先度は高い」欠陥もある。",
  see: ["優先度", "欠陥レポート"], sec: "FL 5.5" },
{ term: "優先度", yomi: "ゆうせんど", en: "priority", cat: "マネジメント",
  def: "欠陥を修正する順番・急ぎ具合。",
  see: ["重要度"], sec: "FL 5.5" },
{ term: "欠陥レポート", yomi: "けっかんれぽーと", en: "defect report", cat: "マネジメント",
  def: "見つかった不正を記録し、解決に必要な情報を伝える文書。識別子、タイトル、テスト対象と環境、再現手順、期待結果と実際の結果、重要度、優先度、状態などを含む。",
  note: "現場の「バグ票」「障害票」「不具合報告」。ISO/IEC/IEEE 29119-3 ではインシデントレポートと呼ぶ。",
  see: ["重要度", "優先度"], sec: "FL 5.5 / TM 2.3" },
{ term: "テスト進捗レポート", yomi: "てすとしんちょくれぽーと", en: "test progress report", cat: "マネジメント",
  def: "テスト中に定期的に作成し、進捗状況、支障とその回避策、メトリクス、新たなリスク、次の期間の計画などを伝えるレポート。",
  see: ["テスト完了レポート"], sec: "FL 5.3.2" },
{ term: "テスト完了レポート", yomi: "てすとかんりょうれぽーと", en: "test completion report", cat: "マネジメント",
  def: "テストの区切り（テストレベルやイテレーションの完了など）で作成し、評価、計画からの逸脱、未解決のリスク、修正されなかった欠陥、学んだ教訓などをまとめるレポート。",
  see: ["テスト進捗レポート"], sec: "FL 5.3.2" },
{ term: "構成管理", yomi: "こうせいかんり", en: "configuration management", cat: "マネジメント",
  def: "作業成果物を構成アイテムとして識別・コントロール・追跡する規律。承認されたものはベースラインとなり、正式な変更コントロールを通じてのみ変更できる。",
  sec: "FL 5.4" },
{ term: "テストピラミッド", yomi: "てすとぴらみっど", en: "test pyramid", cat: "マネジメント",
  def: "テストの粒度の違いを層で表したモデル。下の層ほど小さく速いテストを多く、上の層ほど粒度が粗く遅いテストを少なくする。",
  sec: "FL 5.1.6" },
{ term: "テストの四象限", yomi: "てすとのよんしょうげん", en: "testing quadrants", cat: "マネジメント",
  def: "テストを「ビジネス指向か技術指向か」と「チームを支援するかプロダクトを批評するか」の2軸で4つに分類したモデル（Brian Marick）。",
  sec: "FL 5.1.7" },
{ term: "三点見積り", yomi: "さんてんみつもり", en: "three-point estimation", cat: "マネジメント",
  def: "楽観値 a、最可能値 m、悲観値 b から見積もるエキスパートベースの技法。一般的には E ＝ (a ＋ 4m ＋ b) ÷ 6、標準偏差 SD ＝ (b − a) ÷ 6 で求める。",
  sec: "FL 5.1.4 / TM 2.2.3" },
{ term: "品質コスト", yomi: "ひんしつこすと", en: "cost of quality", cat: "マネジメント",
  def: "品質に関連する労力と欠陥の総コスト。TMシラバスでは、欠陥予防コスト、評価（アプレイザル）コスト、内部失敗コスト、外部失敗コストの4つに分類する（Feigenbaum のアプローチ）。",
  sec: "TM 3.2.1" },
{ term: "ふりかえり", yomi: "ふりかえり", en: "retrospective", cat: "マネジメント",
  def: "チームが自分たちのやり方をレビューし、教訓を把握して改善のアクションを決めるミーティング。イントロダクション、データの収集、改善策の導出、改善アクションの決定、クロージングの流れで行う。",
  note: "現場の「レトロスペクティブ」「振り返り会」「KPT」など。",
  sec: "FL 2.1.6 / TM 1.5.4" },
{ term: "IDEAL", yomi: "あいでぃある", en: "IDEAL", cat: "マネジメント",
  def: "テストプロセス改善のモデル。開始（Initiating）、診断（Diagnosing）、確立（Establishing）、行動（Acting）、学習（Learning）の頭文字。",
  sec: "TM 1.5.1" },
{ term: "チーム全体アプローチ", yomi: "ちーむぜんたいあぷろーち", en: "whole team approach", cat: "マネジメント",
  def: "必要な知識とスキルを持つメンバーなら誰がどの仕事をしてもよく、全員が品質に責任を持つという考え方。エクストリームプログラミングに由来する。",
  note: "「品質はQA担当の仕事」という考え方と対照的。",
  sec: "FL 1.5.2" },

/* ===== AL テストマネジメントの用語 ===== */
{ term: "テストマネージャー", yomi: "てすとまねーじゃー", en: "test manager", cat: "AL テストマネジメント",
  def: "テスト計画、テストモニタリングとコントロール、テスト完了といったテストマネジメント活動に責任を持つ役割。リソースやスケジュールの調整、リスクに基づく判断、ステークホルダーへの報告、テストチームの育成なども担う。アジャイルでは、この役割の一部をチーム全体で分担することもある。",
  note: "「テストリーダー」「QAリーダー」と呼ばれる立場が近い。肩書きよりも、テストマネジメント活動を誰が担っているかで捉えるとよい。",
  see: ["テストステークホルダー", "テスト計画書", "チーム全体アプローチ"], sec: "TM 1.1, 1.2.1" },
{ term: "テストステークホルダー", yomi: "てすとすてーくほるだー", en: "test stakeholder", cat: "AL テストマネジメント",
  def: "テストやその結果に関心を持つ、または影響を受ける人やグループ。開発担当者、プロジェクトマネージャー、プロダクトオーナー、顧客やユーザー、運用チームなどが該当する。テストマネージャーはテストスコープを踏まえたステークホルダー分析で、プロジェクト固有のステークホルダーを識別する。",
  note: "シラバスの例示リストをそのまま当てはめれば済むわけではない。影響力と関心度のマトリクスで分類し、相手ごとに報告の頻度や関わり方を変えるのが実践的。",
  see: ["テストマネージャー", "テスト計画書"], sec: "TM 1.2.1, 1.2.2" },
{ term: "リスクワークショップ", yomi: "りすくわーくしょっぷ", en: "risk workshop", cat: "AL テストマネジメント",
  def: "さまざまな立場のステークホルダーが集まり、品質リスクを洗い出して議論する場。専門家インタビュー、ブレーンストーミング、チェックリスト、過去の経験の参照などと並ぶ、品質リスクの識別技法の1つ。参加者の幅が広いほど重大なリスクの見落としが減る。",
  note: "テスト担当者だけで集まると技術的なリスクに偏りやすい。業務部門や運用担当を呼ぶと、ビジネス影響の大きいリスクが出てきやすい。",
  see: ["プロダクトリスク", "リスクベースドテスト"], sec: "TM 1.3.2" },
{ term: "横型探索", yomi: "よこがたたんさく", en: "breadth-first", cat: "AL テストマネジメント",
  def: "リスクベースドテストでのテスト実行順序の決め方の1つ。まず識別したすべてのリスクに少なくとも1つずつテストを割り当てて先に実行し、その後で残りのテストをリスクレベルの高い順に実行する。プロダクト品質の全体像を早く把握したい場合に向く。",
  see: ["縦型探索", "リスクベースドテスト", "リスクレベル"], sec: "TM 1.3.4" },
{ term: "縦型探索", yomi: "たてがたたんさく", en: "depth-first", cat: "AL テストマネジメント",
  def: "リスクベースドテストでのテスト実行順序の決め方の1つ。テストをリスクレベルの高い順に厳密に実行し、最も高いリスクに関するテストをすべて終えてから次のリスクに進む。最も高いリスクをできるだけ早く軽減したい場合に向く。",
  note: "時間切れになると低いリスクがまったくテストされないまま残ることがある。その点を承知のうえで選ぶ。",
  see: ["横型探索", "リスクベースドテスト", "リスクレベル"], sec: "TM 1.3.4" },
{ term: "残存リスク", yomi: "ざんぞんりすく", en: "residual risk", cat: "AL テストマネジメント",
  def: "テストなどのリスク軽減策を行った後にも残っているリスク。リスクベースドテストでは任意の時点の残存リスクレベルを報告でき、テストを延長するか残存リスクを受け入れてリリースするかの判断材料になる。",
  note: "「未実行テスト○件」と件数だけ報告するより、どのリスクが未軽減かを示すほうがリリース判定の議論がかみ合う。",
  see: ["リスクベースドテスト", "リスクレベル", "テスト完了レポート"], sec: "TM 1.3.4" },
{ term: "重量的な技法と軽量的な技法", yomi: "じゅうりょうてきなぎほうとけいりょうてきなぎほう", en: "heavyweight and lightweight techniques", cat: "AL テストマネジメント",
  def: "リスクベースドテストのリスク分析技法を、形式の度合いで分けたもの。重量的な技法は定義された手順と詳細な文書を用い、幅広いステークホルダーが関与する（ハザード分析、エクスポージャーコスト、FMEA、フォールトツリー解析など）。軽量的な技法は徹底度も労力も小さく、リスク要因を順序尺度で整理する（PRAM、PRISMA、SST など）。",
  note: "重量的な技法はセーフティクリティカルなシステムや規制のある業界で使われることが多い。一般的な業務システムでは軽量的な技法から始めるのが現実的。",
  see: ["FMEA（故障モード影響解析）", "ハザード分析", "フォールトツリー解析", "リスクベースドテスト"], sec: "TM 1.3.5" },
{ term: "FMEA（故障モード影響解析）", yomi: "えふえむいーえー", en: "failure mode and effects analysis (FMEA)", cat: "AL テストマネジメント",
  def: "起こりうる故障モード（品質リスク）ごとに、その原因と影響を洗い出し、重要度・発生の可能性（優先度）・検出のしやすさを評価する重量的な技法。評価結果をもとに、どのリスクから対策やテストを行うかを決める。",
  note: "製造業や車載・医療の分野で使われることが多い。評価項目の点数を掛け合わせた値（RPN）で優先順位を付ける運用がよく見られる。",
  see: ["重量的な技法と軽量的な技法", "フォールトツリー解析", "ハザード分析"], sec: "TM 1.3.5" },
{ term: "ハザード分析", yomi: "はざーどぶんせき", en: "hazard analysis", cat: "AL テストマネジメント",
  def: "各リスクの根底にある危険源（ハザード）を識別し、そこまでさかのぼって分析する重量的な技法。リスクそのものだけでなく、その上流にある発生源を明らかにすることで分析を広げる。",
  see: ["重量的な技法と軽量的な技法", "FMEA（故障モード影響解析）"], sec: "TM 1.3.5" },
{ term: "フォールトツリー解析", yomi: "ふぉーるとつりーかいせき", en: "fault tree analysis (FTA)", cat: "AL テストマネジメント",
  def: "潜在的な故障を起点に、それを引き起こす欠陥、さらにその欠陥を生むエラーへと関連付けをたどり、根本原因が識別できるまで木構造で掘り下げる重量的な技法。トップダウンで原因を分析する。",
  note: "略称の「FTA」で呼ばれることが多い。FMEA が原因から影響へ向かうボトムアップの分析なのに対し、こちらは結果から原因へ向かうトップダウンの分析。",
  see: ["重量的な技法と軽量的な技法", "FMEA（故障モード影響解析）", "根本原因"], sec: "TM 1.3.5" },
{ term: "SMARTの法則", yomi: "すまーとのほうそく", en: "SMART (Specific, Measurable, Achievable, Relevant, Timely)", cat: "AL テストマネジメント",
  def: "テスト目的を明確に書くための基準。具体的（Specific）、測定可能（Measurable）、達成可能（Achievable）、妥当（Relevant）、タイムリー（Timely）の頭文字をとったもの。対象・数値目標・期限がはっきりしたテスト目的にすると、達成したかどうかを判断しやすくなる。",
  note: "「しっかりテストする」「品質を上げる」のような目的は、測定可能性と期限が抜けていることが多い。",
  see: ["テスト戦略", "終了基準"], sec: "TM 1.4.3" },
{ term: "モデルベースのテストプロセス改善", yomi: "もでるべーすのてすとぷろせすかいぜん", en: "model-based test process improvement", cat: "AL テストマネジメント",
  def: "業界で認められた参照モデルと自組織のテストプロセスを比較し、その差分から改善点を見つけるアプローチ。外部の良い実践例を基準にする点が特徴で、代表例として TMMi と TPI NEXT がある。",
  note: "テスト設計技法の「モデルベースドテスト」とは別物。",
  see: ["TMMi", "TPI NEXT", "分析的なテストプロセス改善", "IDEAL"], sec: "TM 1.5.2" },
{ term: "TMMi", yomi: "てぃーえむえむあい", en: "Test Maturity Model integration (TMMi)", cat: "AL テストマネジメント",
  def: "テストプロセスの成熟度を5つのレベルで表すモデル。各レベルで達成すべきプロセスエリアが決まっており、下のレベルから段階的に改善していく。当初は CMMI を補完するものとして開発された。",
  see: ["モデルベースのテストプロセス改善", "TPI NEXT"], sec: "TM 1.5.2" },
{ term: "TPI NEXT", yomi: "てぃーぴーあいねくすと", en: "TPI NEXT", cat: "AL テストマネジメント",
  def: "16のキーエリアと4つの成熟度レベルでテストプロセスを評価するモデル。チェックポイントを使ってキーエリアごとに成熟度をアセスメントし、結果を成熟度マトリクスで可視化する。キーエリアごとに改善を進められる。",
  note: "TMMi が組織全体でレベルを順に上げる段階型なのに対し、TPI NEXT は必要なキーエリアから個別に改善しやすい。",
  see: ["モデルベースのテストプロセス改善", "TMMi"], sec: "TM 1.5.2" },
{ term: "分析的なテストプロセス改善", yomi: "ぶんせきてきなてすとぷろせすかいぜん", en: "analytical test process improvement", cat: "AL テストマネジメント",
  def: "自分たちのプロジェクトやチームのデータを分析して問題を識別し、改善策を導くアプローチ。根本原因分析、尺度・メトリクス・指標を用いた分析、GQM アプローチなどがある。モデルベースのアプローチと組み合わせて使うこともできる。",
  see: ["モデルベースのテストプロセス改善", "GQM（Goal-Question-Metric）", "根本原因"], sec: "TM 1.5.3" },
{ term: "GQM（Goal-Question-Metric）", yomi: "じーきゅーえむ", en: "Goal-Question-Metric (GQM)", cat: "AL テストマネジメント",
  def: "ステークホルダーの情報ニーズに合ったメトリクスを定義・分析するためのフレームワーク。まず測定のゴールを決め、ゴールの達成度を判断するための質問を立て、質問に答えるためのメトリクスを定める。収集したデータで質問に答え、ゴールをアセスメントする。",
  note: "取れるデータから先に集め始めると、使われないメトリクスが増えがち。ゴールから逆算する点がこの手法の肝。",
  see: ["分析的なテストプロセス改善"], sec: "TM 1.5.3" },
{ term: "ROI（投資対効果）", yomi: "あーるおーあい", en: "return on investment (ROI)", cat: "AL テストマネジメント",
  def: "テストツールの導入で得られる利益と、そのためにかかるコストの比較。コストには、ツールの評価・選定や初期トレーニングなど一度だけかかる非経常的なコストと、ライセンス料やメンテナンスなど継続してかかる経常的なコストがある。組織の未熟さによる非効率な使用や、予想を上回るコストなどのリスクも考慮する。",
  note: "ライセンス料だけで比較しがちだが、自動テストのメンテナンス工数のような経常的なコストの見落としが ROI を悪化させる典型例。",
  see: ["テストマネージャー"], sec: "TM 1.6.3" },
{ term: "ワイドバンドデルファイ", yomi: "わいどばんどでるふぁい", en: "Wideband Delphi", cat: "AL テストマネジメント",
  def: "専門家がそれぞれ個別に見積り、結果を持ち寄って差異の理由を議論し、再び見積る、という手順を合意に近づくまで繰り返すエキスパートベースの技法。個人の偏りを抑えつつ、複数の専門家の知見を見積りに反映できる。",
  see: ["プランニングポーカー", "三点見積り"], sec: "FL 5.1.4 / TM 2.2.3" },
{ term: "プランニングポーカー", yomi: "ぷらんにんぐぽーかー", en: "planning poker", cat: "AL テストマネジメント",
  def: "ワイドバンドデルファイの変形で、チームメンバーが数値の書かれたカードを同時に出して見積る技法。値が大きく分かれたら、最大値と最小値を出した人が理由を説明し、再び見積る。アジャイル開発でユーザーストーリーの見積りによく使われる。",
  note: "カードの数値にはフィボナッチ数列に近い値がよく使われる。見積りの単位はストーリーポイントが多い。",
  see: ["ワイドバンドデルファイ"], sec: "FL 5.1.4 / TM 2.2.3" },
{ term: "比率に基づく見積り", yomi: "ひりつにもとづくみつもり", en: "estimation based on ratios", cat: "AL テストマネジメント",
  def: "過去のプロジェクトで得られた比率（たとえば開発工数とテスト工数の比）を使って、今回のテスト工数を見積るメトリクスベースの技法。組織内に信頼できる過去データがあることが前提になる。",
  note: "他社や他部署の比率をそのまま流用すると、プロジェクトの性質が違うために大きく外れることがある。",
  see: ["外挿", "三点見積り"], sec: "FL 5.1.4 / TM 2.2.3" },
{ term: "外挿", yomi: "がいそう", en: "extrapolation", cat: "AL テストマネジメント",
  def: "現在のプロジェクトで早い段階から測定したデータをもとに、残りの作業に必要な工数を推定するメトリクスベースの技法。イテレーティブな開発で、過去のイテレーションの実績から次のイテレーションの工数を見積るのが典型例。",
  see: ["比率に基づく見積り"], sec: "FL 5.1.4 / TM 2.2.3" },
{ term: "欠陥ワークフロー", yomi: "けっかんわーくふろー", en: "defect workflow", cat: "AL テストマネジメント",
  def: "欠陥レポートが作成されてからクローズされるまでにたどる状態と、その遷移のルール。シラバスの単純な例では、オープン（新規）、進行中、却下、解決、クローズの状態がある。終端の状態を1つにする、連続する状態を異なる役割に割り当てるといった設計上のよい実践例がある。",
  note: "「バグのステータス管理」「欠陥のライフサイクル」とも呼ばれる。解決後に誰が確認テストをしてクローズするかを決めておかないと、「修正済み」のまま放置されやすい。",
  see: ["欠陥レポート", "欠陥マネジメント委員会", "確認テスト"], sec: "TM 2.3.1" },
{ term: "欠陥マネジメント委員会", yomi: "けっかんまねじめんといいんかい", en: "defect management committee", cat: "AL テストマネジメント",
  def: "報告された欠陥について、修正するか、いつ修正するか、却下するかなどを判断する機能横断的なチーム。テストマネージャー、開発の代表者、プロジェクトマネジメント、プロダクトマネジメント、プロダクトオーナー、サプライヤーなどが参加する。",
  note: "「トリアージ会議」「バグ判定会議」と呼ばれることが多い。大規模プロジェクトでは専任の欠陥マネージャーを置くこともある。",
  see: ["欠陥ワークフロー", "欠陥レポート", "優先度", "重要度"], sec: "TM 2.3.2" },
{ term: "Belbin のチームの役割", yomi: "べるびんのちーむのやくわり", en: "Belbin Team Roles", cat: "AL テストマネジメント",
  def: "Meredith Belbin による、チーム内で人が自然にとりやすい役割の分類。異なる性格や役割のタイプの人が組み合わさることで、チームが効果的に機能するという考え方に立つ。チームに既にあるスキルと不足しているスキルを識別するのに役立つ。",
  see: ["Tuckman モデル", "Herzberg の動機付け-衛生理論"], sec: "TM 3.1.3" },
{ term: "Tuckman モデル", yomi: "たっくまんもでる", en: "Tuckman model", cat: "AL テストマネジメント",
  def: "チームが発展していく過程を、形成期、混乱期、統一期、機能期、散会期の5つのフェーズで表したモデル。フェーズごとにリーダーに求められるスキルが異なり、たとえば混乱期には対立を解決する能力、機能期には責任を委ねる委任能力が求められる。",
  note: "英語名の forming、storming、norming、performing（と adjourning）で紹介されることも多い。",
  see: ["Belbin のチームの役割", "Herzberg の動機付け-衛生理論"], sec: "TM 3.1.5" },
{ term: "Herzberg の動機付け-衛生理論", yomi: "はーずばーぐのどうきづけえいせいりろん", en: "Herzberg's motivation-hygiene theory", cat: "AL テストマネジメント",
  def: "仕事への満足をもたらす要因（動機付け要因）と、不満を防ぐ要因（衛生要因）は別物だとする理論。承認や評価、責任と自律性、やりがいのあるタスク、昇進と成長がモチベーションを上げる要因で、適切な報酬や快適な労働条件、良好な対人関係などは衛生要因にあたる。衛生要因は欠けると不満につながるが、満たしても意欲を高めるわけではない。",
  note: "給与や設備を改善しても意欲が上がらない、という場面の説明に使える。テストマネジメントとしては、衛生要因の不足を取り除きつつ、動機付け要因を意識的に作ることが求められる。",
  see: ["Tuckman モデル", "Belbin のチームの役割"], sec: "TM 3.1.6" }
];

/* 更新履歴。新しいものを先頭に追加する。date は "YYYY-MM-DD"。
   一番上の日付が、全ページのフッターの「最終更新」に表示される。
   ※ 公開する日に、一番上の日付を実際の公開日に書き換えること */
window.CHANGELOG = [
  { date: "2026-09-28", items: [
    "サイトを公開しました。",
    "Foundation Level（シラバス 2023V4.0.J02）：259問（4択 212問・計算 41問・記述 6問）、模擬試験セット A〜E",
    "Advanced Level テストマネジメント（シラバス V3.0）：225問（4択 208問・計算 12問・記述 5問）、模擬試験セット A〜D",
    "用語集：103語（AL テストマネジメントの用語 26語を含む）"
  ] }
];

window.REPORT_PREFILL = "";
/* 資格ごとの設定と、HTMLを組み立てる共通の関数。
   ブラウザでも、ビルド時（node）でも同じ関数を使うので、書き出したHTMLと画面の表示が必ず一致する。 */
(function(){
  "use strict";
  var W = typeof window !== "undefined" ? window : global.window;

  /* dist は本番の章ごとの出題数（FL：ISTQB CTFL v4.0、TM：ISTQB CTAL-TM v3.0 の試験構成） */
  W.EXAM_CONF = {
    fl: {
      name: "Foundation Level", short: "FL",
      sub: "Foundation Level シラバス 2023V4.0.J02 対応・非公式オリジナル問題",
      src: "出典：ISTQB® テスト技術者資格制度 Foundation Level シラバス（著作権：International Software Testing Qualifications Board）、日本語翻訳版 Version 2023V4.0.J02（著作権：JSTQB®）。",
      qvar: "QUESTIONS", svar: "MOCK_SETS",
      chapters: { 1: "テストの基礎", 2: "ソフトウェア開発ライフサイクル全体を通してのテスト", 3: "静的テスト",
                  4: "テスト分析と設計", 5: "テスト活動のマネジメント", 6: "テストツール" },
      dist: { 1:8, 2:6, 3:4, 4:11, 5:9, 6:2 }, minutes: 60, points: false,
      storeKey: "jstqb-fl-progress-v1"
    },
    tm: {
      name: "Advanced Level テストマネジメント", short: "AL TM",
      sub: "Advanced Level テストマネジメント シラバス V3.0 対応・非公式オリジナル問題",
      src: "出典：ISTQB® テスト技術者資格制度 Advanced Level シラバス テストマネジメント（著作権：International Software Testing Qualifications Board）、日本語翻訳版（著作権：JSTQB®）。",
      qvar: "TM_QUESTIONS", svar: "TM_MOCK_SETS",
      chapters: { 1: "テスト活動のマネジメント", 2: "プロダクトのマネジメント", 3: "チームのマネジメント" },
      dist: { 1:26, 2:15, 3:9 }, minutes: 120, points: true,
      storeKey: "jstqb-altm-progress-v1"
    }
  };

  var R = W.R = {};

  R.exam = function(k){
    var c = W.EXAM_CONF[k], e = {};
    for (var p in c) e[p] = c[p];
    e.key = k;
    e.questions = W[c.qvar] || [];
    e.sets = W[c.svar] || {};
    return e;
  };

  /* 配点：学習目標のKレベルから決める（K2=1点、K3=2点、K4=3点）。k がない問題は1点 */
  R.points = function(e, q){ return e.points ? ({ 3: 2, 4: 3 }[q.k] || 1) : 1; };

  /* 問題IDから毎回同じ並び順を作る（解説ページで正解の位置が偏らないように） */
  R.fixedOrder = function(id, n){
    var h = 2166136261;
    for (var i = 0; i < id.length; i++){ h ^= id.charCodeAt(i); h = Math.imul(h, 16777619); }
    var rnd = function(){ h = Math.imul(h ^ (h >>> 15), 2246822507); h = Math.imul(h ^ (h >>> 13), 3266489909); h ^= h >>> 16; return (h >>> 0) / 4294967296; };
    var a = []; for (var j = 0; j < n; j++) a.push(j);
    for (var k = n - 1; k > 0; k--){ var r = Math.floor(rnd() * (k + 1)); var t = a[k]; a[k] = a[r]; a[r] = t; }
    return a;
  };

  /* 解説の「1つ目」「2つ目と4つ目」などを、画面に表示している選択肢の記号（A〜D）に置き換える */
  R.explText = function(q, order){
    var s = q.expl;
    if (q.type !== "choice" || !order) return s;
    var L = function(d){ return "ABCD"[order.indexOf(+d - 1)]; };
    s = s.replace(/([1-4])つ目と([1-4])つ目/g, "$1と$2つ目");
    return s.replace(/([1-4](?:[・と][1-4])*)つ目/g, function(m, g){
      var sep = g.indexOf("と") >= 0 ? "と" : "・";
      return "選択肢" + g.split(/[・と]/).map(L).sort().join(sep);
    });
  };

  /* ---------- 問題の誤りの報告 ---------- */
  function stripTags(h){ return String(h).replace(/<br\s*\/?>/g, " ").replace(/<[^>]+>/g, "").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim(); }
  /* 報告用の文面。q は "fl:4-36" の形。問題が見つからなければ null */
  R.reportInfo = function(qparam, where){
    var m = /^([a-z]+):([\w-]+)$/.exec(qparam || "");
    if (!m || !W.EXAM_CONF[m[1]]) return null;
    var e = R.exam(m[1]), q = null;
    e.questions.forEach(function(x){ if (x.id === m[2]) q = x; });
    if (!q) return null;
    var head = stripTags(q.q);
    return "【問題・解説の誤り】\n" +
      "資格：" + e.name + "（" + e.short + "）\n" +
      "問題ID：" + q.id + "（第" + q.ch + "章／シラバス " + q.sec + "）\n" +
      (where ? "表示していた場所：" + String(where).slice(0, 60) + "\n" : "") +
      "問題文の冒頭：" + (head.length > 50 ? head.slice(0, 50) + "…" : head) + "\n" +
      "誤りだと思う点：";
  };
  /* 各問題の「誤りを報告」リンク。Googleフォームの事前入力URL（REPORT_PREFILL）があれば、そこへ直接つなぐ */
  R.reportHTML = function(k, q, where){
    var href;
    if (W.REPORT_PREFILL) href = W.REPORT_PREFILL.replace("__TEXT__", encodeURIComponent(R.reportInfo(k + ":" + q.id, where) || ""));
    else href = "contact.html?q=" + encodeURIComponent(k + ":" + q.id) + "&w=" + encodeURIComponent(where || "");
    return '<div><a class="report" href="' + href + '" target="_blank" rel="noopener">この問題の誤りを報告する（新しいタブ）</a></div>';
  };

  /* ---------- 更新履歴 ---------- */
  function fmtDate(d){ var p = d.split("-"); return +p[0] + "年" + (+p[1]) + "月" + (+p[2]) + "日"; }
  R.lastUpdate = function(){ var c = W.CHANGELOG || []; return c.length ? fmtDate(c[0].date) : ""; };
  R.changelogHTML = function(){
    var c = W.CHANGELOG || [];
    if (!c.length) return '<p class="small muted">まだ記録はありません。</p>';
    return '<dl class="clog">' + c.map(function(x){
      return '<dt><time datetime="' + x.date + '">' + fmtDate(x.date) + '</time></dt><dd><ul>' +
        x.items.map(function(t){ return '<li>' + t + '</li>'; }).join("") + '</ul></dd>';
    }).join("") + '</dl>';
  };

  R.setList = function(e, name){
    var byId = {};
    e.questions.forEach(function(q){ byId[q.id] = q; });
    var list = (e.sets[name] || []).map(function(id){ return byId[id]; }).filter(Boolean);
    return list.sort(function(a, b){ return a.ch - b.ch; });
  };

  /* 問題解説：セット一覧 */
  R.explainListHTML = function(){
    return Object.keys(W.EXAM_CONF).map(function(k){
      var e = R.exam(k), names = Object.keys(e.sets);
      return '<div class="card"><h2>' + e.name + '（' + e.short + '）</h2><div class="small muted">模擬試験のセットごとに、問題と正解・解説をまとめて確認できます。</div>' +
        '<div class="setgrid">' + names.map(function(n){
          return '<a class="setbtn" style="text-decoration:none" href="explain-' + k + '-' + n + '.html"><div class="nm">セット' + n + '</div><div class="st">' + e.sets[n].length + '問</div></a>';
        }).join("") + '</div></div>';
    }).join("");
  };

  /* 問題解説：セットごとの問題と解答・解説 */
  R.explainSetHTML = function(k, name){
    var e = R.exam(k), list = R.setList(e, name);
    var html = '<div class="card"><h1 class="pagetitle">' + e.name + '（' + e.short + '）模擬試験 セット' + name + 'の問題と解説</h1>' +
      '<div class="small muted">全' + list.length + '問。問題の後の「解答と解説」を開くと、正解と解説が表示されます。</div></div>';
    list.forEach(function(q, i){
      var p = e.points ? R.points(e, q) : 0;
      var ord = R.fixedOrder(q.id, q.options.length);
      html += '<div class="card" id="q' + (i+1) + '"><div><span class="tag">問' + (i+1) + '</span><span class="tag">第' + q.ch + '章 ' + e.chapters[q.ch] + '</span><span class="tag">シラバス ' + q.sec + '</span>' +
        (p ? '<span class="tag">' + p + '点</span>' : '') + '<span class="qid">ID ' + q.id + '</span></div>' +
        '<div class="qtext">' + q.q + '</div><ol class="olist">' + ord.map(function(oi, n){
          return '<li data-right="' + (oi === q.answer ? 1 : 0) + '"><b>' + "ABCD"[n] + '</b>　' + q.options[oi] + '</li>';
        }).join("") + '</ol>' +
        '<details class="ans"><summary>解答と解説</summary><div style="margin-top:6px"><b>正解：' + "ABCD"[ord.indexOf(q.answer)] + '</b>　' + q.options[q.answer] + '</div>' +
        '<div class="small" style="margin-top:6px">' + R.explText(q, ord) + '</div>' +
        R.reportHTML(k, q, "問題解説 セット" + name + " 問" + (i+1)) + '</details></div>';
    });
    return html;
  };

  /* 用語集 */
  R.glossary = function(){
    return (W.GLOSSARY || []).slice().sort(function(a, b){ return a.yomi.localeCompare(b.yomi, "ja"); });
  };
  R.glossaryCats = function(){
    var cats = ["すべて"];
    (W.GLOSSARY || []).forEach(function(g){ if (cats.indexOf(g.cat) < 0) cats.push(g.cat); });
    return cats;
  };
  R.glossaryCatsHTML = function(cur){
    return R.glossaryCats().map(function(c){
      return '<button class="chip' + (c === cur ? " on" : "") + '" data-cat="' + c + '" aria-pressed="' + (c === cur) + '">' + c + '</button>';
    }).join("");
  };
  R.glossaryListHTML = function(cat, kw){
    var norm = function(t){ return (t.normalize ? t.normalize("NFKC") : t).toLowerCase(); };   /* 全角・半角の違いを無視 */
    kw = norm((kw || "").trim());
    var hit = R.glossary().filter(function(g){
      if (cat !== "すべて" && g.cat !== cat) return false;
      if (!kw) return true;
      return norm([g.term, g.yomi, g.en, g.def, g.note || ""].join(" ")).indexOf(kw) >= 0;
    });
    return hit.length ? hit.map(function(g){
      return '<div class="gl-item" id="gl-' + encodeURIComponent(g.term) + '"><div><h2 class="gl-term">' + g.term + '</h2><span class="gl-en">' + g.en + '</span></div>' +
        '<div style="margin-top:4px">' + g.def + '</div>' +
        (g.note ? '<div class="gl-note"><b>現場では：</b>' + g.note + '</div>' : '') +
        '<div class="gl-meta">分類：' + g.cat + '　／　シラバス：' + g.sec +
        (g.see && g.see.length ? '　／　関連：' + g.see.map(function(t){ return '<a href="#gl-' + encodeURIComponent(t) + '" data-see="' + t + '">' + t + '</a>'; }).join("、") : '') + '</div></div>';
    }).join("") : '<div class="small muted">該当する用語がありません。</div>';
  };
})();
